const dict = { fr, en, de };

export const lang = writable('fr');
export const t = derived(lang, ($lang) => (key, vars) => {
  let s = dict[$lang]?.[key] ?? dict.fr[key] ?? key;
  if (vars) for (const [k, v] of Object.entries(vars)) s = s.replaceAll('{' + k + '}', v);
  return s;
});
